package jp.tapmarker;
import android.accessibilityservice.AccessibilityService;
import android.app.ActivityOptions;
import android.app.AlertDialog;
import android.content.Intent;
import android.graphics.Rect;
import android.view.accessibility.*;
import java.util.*;
/** Public multi-window requests only; actual windows must be confirmed. */
final class SplitLauncher {
 final TapService s;int generation;boolean preparing;
 SplitLauncher(TapService s){this.s=s;}
 void cancel(){generation++;preparing=false;}
 String[] targets(){String saved=s.getSharedPreferences("multiWindow",0).getString("targets",UsagiPreset.APP+","+FarmPreset.APP);return saved.isEmpty()?new String[0]:saved.split(",");}
 boolean freeform(){return s.getSharedPreferences("multiWindow",0).getBoolean("freeform",false);}
 int virtualLimit(){return VirtualLoadPolicy.limit(s.getSharedPreferences("multiWindow",0).getInt("virtualLimit",VirtualLoadPolicy.DEFAULT_LIMIT));}
 boolean virtualCountAllowed(int count){if(VirtualLoadPolicy.allows(count,virtualLimit()))return true;s.pilot.note(s.getString(R.string.virtual_limit_exceeded,virtualLimit()));return false;}
 void choose(){
  final int[] choice={virtualLimit()};
  AlertDialog dialog=new UiStrings.DialogBuilder(s).setTitle("同時稼働数").setSingleChoiceItems(new String[]{"2アプリ","3アプリ","4アプリ"},choice[0]-2,(d,i)->choice[0]=i+2).setPositiveButton("アプリを選択",(d,w)->{s.getSharedPreferences("multiWindow",0).edit().putInt("virtualLimit",choice[0]).apply();chooseApps();}).setNegativeButton("閉じる",null).create();dialog.getWindow().setType(android.view.WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);dialog.show();
 }
 void chooseApps(){
  LinkedHashSet<String> candidates=new LinkedHashSet<>();candidates.addAll(Arrays.asList(PresetRegistry.APPS));candidates.addAll(Arrays.asList(GameTarget.ADDED_APPS));
  for(String key:s.getSharedPreferences("markers",0).getAll().keySet())if(key.startsWith("profile:"))candidates.add(GameTarget.packageName(key.substring(8)));
  for(String key:s.getSharedPreferences("appPhases",0).getAll().keySet())if(key.indexOf(':')<0&&key.contains("."))candidates.add(GameTarget.packageName(key));
  candidates.addAll(Arrays.asList(targets()));ArrayList<String> apps=new ArrayList<>();for(String pkg:candidates)if(s.getPackageManager().getLaunchIntentForPackage(pkg)!=null)apps.add(pkg);
  if(apps.isEmpty()){s.pilot.note("先に対象アプリをインストール・登録してください");return;}
  String[] labels=new String[apps.size()];boolean[] selected=new boolean[apps.size()];Set<String> old=new HashSet<>(Arrays.asList(targets()));for(int i=0;i<labels.length;i++){labels[i]=s.appLabel(apps.get(i));selected[i]=old.contains(apps.get(i));}
  AlertDialog dialog=new UiStrings.DialogBuilder(s).setTitle(s.getString(R.string.virtual_app_selection_title,virtualLimit())).setMultiChoiceItems(labels,selected,(d,i,on)->selected[i]=on).setPositiveButton("配置方式へ",(d,w)->{ArrayList<String> chosen=new ArrayList<>();for(int i=0;i<selected.length;i++)if(selected[i])chosen.add(apps.get(i));if(chosen.isEmpty()){s.pilot.note("対象未選択");return;}s.getSharedPreferences("multiWindow",0).edit().putString("targets",android.text.TextUtils.join(",",chosen)).apply();mode(chosen.size());}).setNegativeButton("閉じる",null).setNeutralButton("同時稼働数",(d,w)->choose()).create();dialog.getWindow().setType(android.view.WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);dialog.show();
 }
 void mode(int count){AlertDialog dialog=new UiStrings.DialogBuilder(s).setTitle("画面の開き方").setItems(new String[]{"端末だけで仮想画面（おすすめ）","接続済みの仮想画面を開く","PCに各画面を表示","その他の表示方式"},(d,i)->{if(i==2){PcControl.requestPlacement(s,targets());return;}if(i==3){advancedMode(count);return;}if(!virtualCountAllowed(count))return;PcControl.cancelPlacement(s,"端末の仮想画面を選択しました");if(i==1&&VirtualBridgeProvider.connected()!=null)s.pilot.virtualWindows.openAdb();else s.pilot.wireless.guide(true);}).setNegativeButton("閉じる",null).create();dialog.getWindow().setType(android.view.WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);dialog.show();}
 void advancedMode(int count){AlertDialog dialog=new UiStrings.DialogBuilder(s).setTitle("ウインドウの開き方").setItems(new String[]{"分割表示（端末の対応数まで）","自由ウインドウ（対応端末のみ）","既に表示したウインドウで開始","仮想画面（標準権限・Shizukuなし）","仮想画面（Shizuku接続）","仮想画面（ADB接続・Shizuku不要）","仮想画面（端末内接続・PC不要）","PC（PCに各画面を表示して自律）"},(d,i)->{if(i==7){PcControl.requestPlacement(s,targets());return;}if(i>=3&&!virtualCountAllowed(count))return;PcControl.cancelPlacement(s,"別の配置方式を選択しました");if(i==6){s.pilot.wireless.guide(true);return;}if(i==5){s.pilot.virtualWindows.openAdb();return;}if(i>=3){s.pilot.virtualWindows.open(i==4);return;}if(i==2){if(s.pilot.virtualSession())s.pilot.virtualWindows.startAutonomy();else s.pilot.splitPilot.start();return;}s.getSharedPreferences("multiWindow",0).edit().putBoolean("freeform",i==1).apply();if(i==0&&count>2){s.pilot.note("3画面以上は自由ウインドウ方式を選択してください");return;}open();}).create();dialog.getWindow().setType(android.view.WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);dialog.show();}
 void launch(String pkg,int index,int count){Intent intent=s.getPackageManager().getLaunchIntentForPackage(pkg);if(intent==null)throw new IllegalArgumentException(s.appLabel(pkg)+"が未インストール");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(freeform()){android.util.DisplayMetrics dm=new android.util.DisplayMetrics();s.wm.getDefaultDisplay().getRealMetrics(dm);int[] b=MultiWindowLayout.cell(dm.widthPixels,dm.heightPixels,count,index);ActivityOptions options=ActivityOptions.makeBasic().setLaunchBounds(new Rect(b[0],b[1],b[2],b[3]));s.startActivity(intent,options.toBundle());}else{s.startActivity(intent.addFlags(index>0?Intent.FLAG_ACTIVITY_LAUNCH_ADJACENT:0));}}
 void open(){s.stop();String[] apps=targets();if(apps.length==0)return;int expected=++generation;preparing=true;s.compactPanel(true);s.pilot.note(apps.length+"画面の起動を要求中");launchNext(apps,0,expected);}
 void launchNext(String[] apps,int i,int expected){if(expected!=generation)return;if(i==apps.length){verify(expected,0,false);return;}try{launch(apps[i],i,apps.length);}catch(Exception e){preparing=false;s.pilot.note("起動失敗："+e.getMessage());return;}s.h.postDelayed(()->launchNext(apps,i+1,expected),700);}
 Rect bounds(String pkg){for(AccessibilityWindowInfo w:s.getWindows()){if(w.getType()!=AccessibilityWindowInfo.TYPE_APPLICATION)continue;AccessibilityNodeInfo n=w.getRoot();if(n==null)continue;boolean match=pkg.contentEquals(n.getPackageName()==null?"":n.getPackageName());n.recycle();if(match){Rect r=new Rect();w.getBoundsInScreen(r);if(!r.isEmpty())return r;}}return null;}
 boolean exposed(String pkg,Rect rect){AccessibilityWindowInfo target=null;for(AccessibilityWindowInfo w:s.getWindows()){AccessibilityNodeInfo n=w.getRoot();if(n==null)continue;boolean match=pkg.contentEquals(n.getPackageName()==null?"":n.getPackageName());n.recycle();if(match&&w.getType()==AccessibilityWindowInfo.TYPE_APPLICATION){target=w;break;}}if(target==null)return false;for(AccessibilityWindowInfo w:s.getWindows())if(w.getType()==AccessibilityWindowInfo.TYPE_APPLICATION&&w.getId()!=target.getId()&&w.getLayer()>target.getLayer()){Rect other=new Rect();w.getBoundsInScreen(other);if(Rect.intersects(rect,other))return false;}return true;}
 boolean ready(){String[] apps=targets();for(String pkg:apps){Rect r=bounds(pkg);if(r==null||!exposed(pkg,r))return false;}return apps.length>0;}
 void verify(int expected,int attempt,boolean fallback){if(expected!=generation)return;if(ready()){preparing=false;s.pilot.splitPilot.start(targets());return;}if(attempt==5&&!fallback&&!freeform()&&targets().length==2){recents(expected,0,false);return;}if(attempt<60){if(attempt==6)s.pilot.note("要求した配置を確認できません / Android側で分割・自由ウインドウを配置してください。表示確認後に自律開始");s.h.postDelayed(()->verify(expected,attempt+1,fallback),500);return;}preparing=false;s.pilot.note("配置未完了 / 表示後に「表示中の対象を自律」を押してください");}
 void recents(int expected,int attempt,boolean menu){if(expected!=generation)return;if(attempt==0){try{launch(targets()[0],0,2);}catch(Exception ignored){}s.h.postDelayed(()->{if(expected==generation){s.performGlobalAction(AccessibilityService.GLOBAL_ACTION_RECENTS);s.h.postDelayed(()->recents(expected,1,false),700);}},500);return;}AccessibilityNodeInfo root=s.getRootInActiveWindow();boolean split=false,opened=false;if(root!=null){String pkg=String.valueOf(root.getPackageName());if(!pkg.equals(targets()[0])&&!pkg.equals(targets()[1])&&!pkg.equals("jp.tapmarker")){split=findClick(root,true);if(!split&&!menu)opened=findClick(root,false);}root.recycle();}if(split){s.h.postDelayed(()->{if(expected!=generation)return;try{launch(targets()[1],1,2);}catch(Exception ignored){}verify(expected,0,true);},700);return;}if(attempt<6){final boolean nextMenu=menu||opened;s.h.postDelayed(()->recents(expected,attempt+1,nextMenu),500);return;}s.pilot.note("最近使ったアプリで分割メニューを選択してください / 配置確認を待機中");verify(expected,6,true);}
 boolean findClick(AccessibilityNodeInfo n,boolean split){String text=String.valueOf(n.getText()),desc=String.valueOf(n.getContentDescription());boolean matches=split?MultiWindowLayout.splitLabel(text)||MultiWindowLayout.splitLabel(desc):desc.contains(s.appLabel(targets()[0]))&&(desc.contains("アイコン")||desc.toLowerCase(java.util.Locale.ROOT).contains("icon"));if(matches&&n.isVisibleToUser()&&n.isEnabled()&&n.isClickable()&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child==null)continue;boolean found=findClick(child,split);child.recycle();if(found)return true;}return false;}
}
